// Basic allocation size calculations:
new T                    // operator new(sizeof(T))
new T[N]                 // operator new[](sizeof(T)*N + overhead)

// Placement new with additional arguments:
new (arena) T            // operator new(sizeof(T), arena)
new (align, pool) T[N]   // operator new[](sizeof(T)*N + overhead, align, pool)

// Array overhead (conceptual layout):
// Memory layout for new T[5]:
// [overhead: size=5] [T] [T] [T] [T] [T]
//                     ^
//                     Returned pointer (offset from allocation start)

// Alignment for char arrays:
char* buffer = new char[100];  // Suitable for placement new of any type
void* aligned = buffer;         // Guaranteed aligned for fundamental types
Widget* w = new (aligned) Widget;  // Safe: alignment preserved

