#include <iostream>
#include <new>
#include <cstddef>

// Track allocation sizes
void* operator new(std::size_t size) {
    std::cout << "operator new(" << size << ")\n";
    void* ptr = std::malloc(size);
    if (!ptr) throw std::bad_alloc();
    return ptr;
}

void* operator new[](std::size_t size) {
    std::cout << "operator new[](" << size << ")\n";
    void* ptr = std::malloc(size);
    if (!ptr) throw std::bad_alloc();
    return ptr;
}

void operator delete(void* ptr) noexcept {
    std::cout << "operator delete\n";
    std::free(ptr);
}

void operator delete[](void* ptr) noexcept {
    std::cout << "operator delete[]\n";
    std::free(ptr);
}

// Placement new with custom arguments
void* operator new(std::size_t size, int priority, const char* tag) {
    std::cout << "operator new(" << size << ", " << priority 
              << ", \"" << tag << "\")\n";
    void* ptr = std::malloc(size);
    if (!ptr) throw std::bad_alloc();
    return ptr;
}

struct Widget {
    int data[10];  // 40 bytes on most platforms
    ~Widget() { std::cout << "  ~Widget()\n"; }
};

int main() {
    std::cout << "sizeof(Widget) = " << sizeof(Widget) << "\n\n";

    // Single object allocation
    std::cout << "1. new Widget:\n";
    Widget* w1 = new Widget;
    std::cout << "   Allocated exactly sizeof(Widget) bytes\n\n";
    delete w1;

    // Array allocation with overhead
    std::cout << "\n2. new Widget[5]:\n";
    Widget* arr = new Widget[5];
    std::size_t expected = sizeof(Widget) * 5;  // 200 bytes
    std::cout << "   Expected: " << expected << " bytes (5 * " 
              << sizeof(Widget) << ")\n";
    std::cout << "   Actual: 200 + overhead (typically 8 bytes for size)\n\n";
    delete[] arr;

    // Placement new with custom arguments
    std::cout << "\n3. new(priority, tag) Widget:\n";
    Widget* w2 = new (10, "important") Widget;
    std::cout << "   Arguments passed: size, priority, tag\n";
    delete w2;

    // Char array for placement new (alignment guarantee)
    std::cout << "\n4. char array for placement new:\n";
    char* buffer = new char[sizeof(Widget)];
    std::cout << "   Allocated char[" << sizeof(Widget) << "]\n";
    std::cout << "   Buffer is properly aligned for any fundamental type\n";

    // Placement new into buffer
    Widget* w3 = new (buffer) Widget;  // No allocation, just construction
    std::cout << "   Placement new at " << (void*)w3 << "\n";
    std::cout << "   Buffer address:   " << (void*)buffer << "\n";
    std::cout << "   Addresses match (no overhead for placement new)\n";

    w3->~Widget();  // Manual destruction
    delete[] buffer;

    return 0;
}

// Typical output (platform-dependent):
// sizeof(Widget) = 40
//
// 1. new Widget:
// operator new(40)
//    Allocated exactly sizeof(Widget) bytes
// ~Widget()
// operator delete
//
// 2. new Widget[5]:
// operator new[](208)  <- 200 + 8 bytes overhead on most platforms
//    Expected: 200 bytes (5 * 40)
//    Actual: 200 + overhead (typically 8 bytes for size)
// ~Widget()
// ~Widget()
// ~Widget()
// ~Widget()
// ~Widget()
// operator delete[]
//
// 3. new(priority, tag) Widget:
// operator new(40, 10, "important")
//    Arguments passed: size, priority, tag
// operator delete
//
// 4. char array for placement new:
// operator new[](40)
//    Allocated char[40]
//    Buffer is properly aligned for any fundamental type
//    Placement new at 0x...
//    Buffer address:   0x...
//    Addresses match (no overhead for placement new)
// ~Widget()
// operator delete[]
